package com.python.interviewcards

object LearningHints {
    fun analogy(category:String)=when(category) {
        "01"->"Имена переменных похожи на ярлыки, прикреплённые к объектам. Переклеить ярлык и изменить сам предмет — разные действия."
        "02"->"Список похож на пронумерованную полку, словарь — на поиск по ключу, генератор — на конвейер, который выдаёт следующий предмет по запросу."
        "03"->"Функции и объекты — участники команды с определённой ответственностью. Интерфейс говорит, что участник умеет делать, а композиция соединяет участников."
        "04"->"Один повар может переключаться между заказами во время ожидания; два повара могут работать одновременно. Конкурентность и параллелизм различаются."
        "05"->"Транзакция объединяет согласованные записи; индекс напоминает указатель в книге, который ускоряет поиск, но тоже требует обслуживания."
        "06"->"Запрос проходит через пропускной пункт, маршрут и исполнителя. ORM переводит работу с моделями в запросы к базе, а не устраняет стоимость этих запросов."
        "07"->"Аутентификация проверяет пропуск, авторизация — право войти именно в эту комнату. Проверка адреса и содержимого входа нужна даже при наличии пропуска."
        "08"->"Тест — воспроизводимый эксперимент: известные условия, действие и проверяемый результат. Профилирование сначала показывает, где уходит время."
        "09"->"Контейнер — упакованное рабочее место, но его ресурсы и жизненный цикл всё равно нужно контролировать. Надёжный деплой допускает несколько версий одновременно."
        "10"->"Алгоритм — последовательность шагов, для которой нужно объяснить результат, крайние случаи и расход ресурсов, а не только запомнить код."
        else->"Разберите операцию как последовательность шагов: входные данные, проверка правил, обращение к ресурсам, результат и возможный сбой."
    }
    fun mistake(category:String)=when(category) {
        "01","02"->"Путать имя и объект, равенство и идентичность или среднюю сложность с гарантией худшего случая. Проверьте поведение на небольшом примере."
        "03"->"Заучить название паттерна, не объяснив его контракт, ограничения и причину выбора. Приведите конкретный вызов и ожидаемое поведение."
        "04"->"Считать async автоматическим параллелизмом или предполагать, что GIL защищает многошаговую бизнес-операцию."
        "05","06"->"Оценивать только отдельный запрос, забыв о транзакции, N+1, конкурентном доступе и границах между БД и внешними системами."
        "07"->"Принимать ограничение интерфейса или браузера за серверную проверку прав. Проверяйте доступ к каждому конкретному ресурсу."
        "08"->"Подменить все зависимости и проверить только число вызовов, не заметив ошибочный результат или нарушение контракта."
        "09"->"Держать общее состояние в памяти worker и ожидать, что оно доступно всем процессам и переживает перезапуск."
        else->"Не проверить пустой вход, повторные значения, недопустимые параметры и сложность решения."
    }
}
